head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setColumnWidth]<br/>Body Column 정보를 사용하여 특정 Column 의 너비를 설정합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터로 너비를 변경할 Column 의 인덱스값을 설정할 수 있어야 합니다.",
        "Column 의 인덱스는 0 부터 시작하며 숨겨진 Column 과 RowNum, RowStatus Column 도 포함하여 인덱스가 설정되어야 합니다.",
        "size(필수) 파라미터로 변경할 Column 의 너비를 픽셀(px) 단위 숫자로 설정할 수 있어야 합니다.",
        "setColumnWidth() 메소드로 Column 의 너비가 변경되면 oncolumnwidthchange 이벤트가 발생해야 합니다.",
        "setColumnWidth() 메소드로 Column 의 너비가 변경되어도 onaftercolumnresize 이벤트는 발생하지 않아야 합니다.",
        "AutoFit 기능이 활성화 되어 있으면 setColumnWidth() 메소드 대상의 Column 너비가 변경된 후 나머지 Column 의 너비가 자동으로 재분배되어야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 이벤트 발생 추적 플래그 초기화
    scwin.gVar = { "widthChangeFired": false, "afterResizeFired": false };

    // 숨겨진 Column 포함 인덱스 안내 라벨 (가장 먼저 생성)
    $c.gcm.createLabel('label="Column(1) 은 숨김 상태입니다. 인덱스는 숨겨진 Column 도 포함하여 0 부터 부여됩니다."', '', 'label1');

    // 조건 설정 (autoFit 옵션 con 적용)
    let autoFit = con_autoFit.getValue();

    let properties = {
        autoFit: autoFit,
        dataList: "data:dlt_bind",
    };

    let cList = $c.gcm.createCList(properties);

    // 이벤트 바인딩 (oncolumnwidthchange 발생 / onaftercolumnresize 미발생 확인)
    let eList = $c.gcm.createEList(["oncolumnwidthchange", "onaftercolumnresize"]);

    // dataList 생성
    $c.gcm.createBasicDataList('', '', 'dlt_bind');

    // target 생성
    await $c.gcm.createBasicGridView(cList, eList);

    // 두번째 Column(인덱스 1) 숨김 처리
    target1.setColumnVisible(1, false);
}



scwin.target1_oncolumnwidthchange = function (info) {
    scwin.gVar.widthChangeFired = true;
    wf_body_bottom.getObj("scwin").setReturnValue("oncolumnwidthchange : 발생");
    wf_body_bottom.getObj("scwin").setReturnValue("info.columnIndex : " + info.columnIndex);
    wf_body_bottom.getObj("scwin").setReturnValue("info.columnID : " + info.columnID);
    wf_body_bottom.getObj("scwin").setReturnValue("info.oldWidth : " + info.oldWidth);
    wf_body_bottom.getObj("scwin").setReturnValue("info.newWidth : " + info.newWidth);
}



scwin.target1_onaftercolumnresize = function (columnIndex, oldColumnWidth, newWidth) {
    scwin.gVar.afterResizeFired = true;
}



scwin.btn_setColumnWidth_onclick = function () {
    let columnInfo = Number(par_columnInfo.getValue());
    let size = Number(par_size.getValue());

    // 이벤트 발생 플래그 초기화
    scwin.gVar.widthChangeFired = false;
    scwin.gVar.afterResizeFired = false;

    // 인덱스 호출
    target1.setColumnWidth(columnInfo, size);
    wf_body_bottom.getObj("scwin").setReturnValue("setColumnWidth(" + columnInfo + ", " + size + ")");
}



scwin.btn_checkColumnWidth_onclick = function () {
    let columnInfo = Number(par_columnInfo.getValue());

    // 변경된 Column 의 너비 확인 (header column 은 1부터 시작)
    let thEl = document.querySelector("th[id*='target1_column" + (columnInfo + 1) + "']");

    if (thEl) {
        wf_body_bottom.getObj("scwin").setReturnValue("Column(" + columnInfo + ") width : " + thEl.offsetWidth);
    }

    // onaftercolumnresize 미발생 확인
    wf_body_bottom.getObj("scwin").setReturnValue("onaftercolumnresize : " + (scwin.gVar.afterResizeFired ? "발생" : "미발생"));
}



scwin.btn_checkAutoFit_onclick = function () {
    // AutoFit 활성 시 나머지 Column 의 너비 자동 재분배 확인 (대상 외 Column 너비 출력)
    let widths = [];

    for (var i = 0; i < 4; i++) {
        let thEl = document.querySelector("th[id*='target1_column" + (i + 1) + "']");
        if (thEl) {
            widths.push("Column(" + i + ") : " + thEl.offsetWidth);
        }
    }

    wf_body_bottom.getObj("scwin").setReturnValue("autoFit = " + con_autoFit.getValue());
    wf_body_bottom.getObj("scwin").setReturnValue(widths.join(" / "));
}
